  "metadata": "{\"compiler\":{\"version\":\"0.8.28+commit.7893614a\"},\"language\":\"Solidity\",\"output\":{\"abi\":[{\"inputs\":[{\"internalType\":\"address\",\"name\":\"priceFeedAddress\",\"type\":\"address\"}],\"stateMutability\":\"nonpayable\",\"type\":\"constructor\"},{\"stateMutability\":\"payable\",\"type\":\"fallback\"},{\"inputs\":[],\"name\":\"MINIMUM_USD\",\"outputs\":[{\"internalType\":\"uint256\",\"name\":\"\",\"type\":\"uint256\"}],\"stateMutability\":\"view\",\"type\":\"function\"},{\"inputs\":[{\"internalType\":\"address\",\"name\":\"\",\"type\":\"address\"}],\"name\":\"addressToAmountFunded\",\"outputs\":[{\"internalType\":\"uint256\",\"name\":\"\",\"type\":\"uint256\"}],\"stateMutability\":\"view\",\"type\":\"function\"},{\"inputs\":[],\"name\":\"fund\",\"outputs\":[],\"stateMutability\":\"payable\",\"type\":\"function\"},{\"inputs\":[{\"internalType\":\"uint256\",\"name\":\"\",\"type\":\"uint256\"}],\"name\":\"funders\",\"outputs\":[{\"internalType\":\"address\",\"name\":\"\",\"type\":\"address\"}],\"stateMutability\":\"view\",\"type\":\"function\"},{\"inputs\":[],\"name\":\"getPriceFeed\",\"outputs\":[{\"internalType\":\"contract AggregatorV3Interface\",\"name\":\"\",\"type\":\"address\"}],\"stateMutability\":\"view\",\"type\":\"function\"},{\"inputs\":[],\"name\":\"owner\",\"outputs\":[{\"internalType\":\"address\",\"name\":\"\",\"type\":\"address\"}],\"stateMutability\":\"view\",\"type\":\"function\"},{\"inputs\":[],\"name\":\"withdraw\",\"outputs\":[],\"stateMutability\":\"nonpayable\",\"type\":\"function\"},{\"stateMutability\":\"payable\",\"type\":\"receive\"}],\"devdoc\":{\"kind\":\"dev\",\"methods\":{},\"version\":1},\"userdoc\":{\"kind\":\"user\",\"methods\":{},\"version\":1}},\"settings\":{\"compilationTarget\":{\"project/contracts/FundMe.sol\":\"FundMe\"},\"evmVersion\":\"cancun\",\"libraries\":{},\"metadata\":{\"bytecodeHash\":\"ipfs\",\"useLiteralContent\":true},\"optimizer\":{\"enabled\":false,\"runs\":200},\"remappings\":[\"project/:@chainlink/contracts/=npm/@chainlink/contracts@1.5.0/\"]},\"sources\":{\"npm/@chainlink/contracts@1.5.0/src/v0.8/shared/interfaces/AggregatorV3Interface.sol\":{\"content\":\"// SPDX-License-Identifier: MIT\\npragma solidity ^0.8.0;\\n\\n// solhint-disable-next-line interface-starts-with-i\\ninterface AggregatorV3Interface {\\n  function decimals() external view returns (uint8);\\n\\n  function description() external view returns (string memory);\\n\\n  function version() external view returns (uint256);\\n\\n  function getRoundData(\\n    uint80 _roundId\\n  ) external view returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);\\n\\n  function latestRoundData()\\n    external\\n    view\\n    returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);\\n}\\n\",\"keccak256\":\"0x257a8d28fa83d3d942547c8e129ef465e4b5f3f31171e7be4739a4c98da6b4f0\",\"license\":\"MIT\"},\"project/contracts/FundMe.sol\":{\"content\":\"// SPDX-License-Identifier: MIT\\npragma solidity ^0.8.18;\\n\\nimport {AggregatorV3Interface} from \\\"@chainlink/contracts/src/v0.8/shared/interfaces/AggregatorV3Interface.sol\\\";\\nimport {PriceConverter} from \\\"./PriceConverter.sol\\\";\\n\\ncontract FundMe {\\n\\n    // Attach library functions to uint256 type\\n    // So you can call ethAmount.getConversionRate() directly\\n    using PriceConverter for uint256;\\n\\n    // Minimum funding amount in USD (18 decimals to match wei math)\\n    uint256 public constant MINIMUM_USD = 5e18; // $5\\n\\n    address public immutable owner;\\n\\n    // Chainlink ETH/USD price feed contract\\n    AggregatorV3Interface private s_priceFeed;\\n\\n    // Tracks how much each address has funded\\n    mapping(address => uint256) public addressToAmountFunded;\\n\\n    // List of all funders\\n    address[] public funders;\\n\\n    constructor(address priceFeedAddress) {\\n        owner = msg.sender;\\n\\n        // Pass in the Chainlink price feed address for your network\\n        // Sepolia ETH/USD: 0x694AA1769357215DE4FAC081bf1f309aDC325306\\n        s_priceFeed = AggregatorV3Interface(priceFeedAddress);\\n    }\\n\\n    // payable = this function can receive ETH\\n    function getPriceFeed() public view returns (AggregatorV3Interface) {\\n    return s_priceFeed;\\n}\\n    function fund() public payable {\\n        // msg.value is in wei \\u2014 convert it to USD using the library\\n        // then check it meets the minimum\\n        require(\\n            msg.value.getConversionRate(s_priceFeed) >= MINIMUM_USD,\\n            \\\"Send at least $5 worth of ETH\\\"\\n        );\\n\\n        addressToAmountFunded[msg.sender] += msg.value;\\n        funders.push(msg.sender);\\n    }\\n\\n    // Only the deployer can withdraw\\n    function withdraw() public onlyOwner {\\n        // Reset all funder balances\\n        for (uint256 i = 0; i < funders.length; i++) {\\n            addressToAmountFunded[funders[i]] = 0;\\n        }\\n\\n        // Clear funders array\\n        funders = new address[](0);\\n\\n        // Send entire contract balance to owner\\n        (bool success, ) = owner.call{value: address(this).balance}(\\\"\\\");\\n        require(success, \\\"Withdraw failed\\\");\\n    }\\n\\n    // Modifier: reusable guard that checks caller is owner\\n    modifier onlyOwner() {\\n        require(msg.sender == owner, \\\"Not the owner\\\");\\n        _; // continues executing the function body\\n    }\\n\\n    // Fallback \\u2014 handles ETH sent directly without calling fund()\\n    receive() external payable {\\n        fund();\\n    }\\n\\n    fallback() external payable {\\n        fund();\\n    }\\n}\\n\",\"keccak256\":\"0x7e46842ac61586fa867ed6c44a28e5966b65af8e7d5093c8cec4d70096e46ea1\",\"license\":\"MIT\"},\"project/contracts/PriceConverter.sol\":{\"content\":\"// SPDX-License-Identifier: MIT\\npragma solidity ^0.8.18;\\n\\n// Chainlink interface \\u2014 tells Solidity what functions the price feed contract has\\nimport {AggregatorV3Interface} from \\\"@chainlink/contracts/src/v0.8/shared/interfaces/AggregatorV3Interface.sol\\\";\\n\\nlibrary PriceConverter {\\n    \\n    // Fetches the current ETH/USD price from Chainlink\\n    // Returns price with 8 decimal places (e.g., 3000_00000000 = $3000)\\n    function getPrice(AggregatorV3Interface priceFeed) internal view returns (uint256) {\\n        // latestRoundData() returns multiple values; we only need `answer` (the price)\\n        (, int256 answer, , , ) = priceFeed.latestRoundData();\\n\\n        // Convert to 18 decimals to match ETH (wei), answer has 8 decimals\\n        return uint256(answer * 1e10);\\n    }\\n\\n    // Converts an ETH amount (in wei) to its USD value\\n    function getConversionRate(uint256 ethAmount, AggregatorV3Interface priceFeed) internal view returns (uint256) {\\n        uint256 ethPrice = getPrice(priceFeed);\\n\\n        // Both ethPrice and ethAmount have 18 decimals\\n        // Dividing by 1e18 brings it back to a normal number\\n        uint256 ethAmountInUsd = (ethPrice * ethAmount) / 1e18;\\n\\n        return ethAmountInUsd;\\n    }\\n}\\n\",\"keccak256\":\"0x1024a17245c5743f3d24ddfa15a72403d11686643267001e81a1836a4180cff4\",\"license\":\"MIT\"}},\"version\":1}",
